@Composable
fun CameraPermissionGate(onGranted: () -> Unit) {
    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { granted -> if (granted) onGranted() }
    Button(onClick = { launcher.launch(Manifest.permission.CAMERA) }) {
        Text("Mở camera")
    }
}

sealed interface CameraAccess {
    data object Granted : CameraAccess
    data object CanRequest : CameraAccess
    data object NeedsSettings : CameraAccess
}

fun cameraAccess(activity: Activity): CameraAccess {
    if (ContextCompat.checkSelfPermission(activity, Manifest.permission.CAMERA)
        == PackageManager.PERMISSION_GRANTED) return CameraAccess.Granted
    return if (ActivityCompat.shouldShowRequestPermissionRationale(
            activity, Manifest.permission.CAMERA
        )) CameraAccess.CanRequest else CameraAccess.CanRequest
}

fun shouldRequestNotifications(): Boolean =
    Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU

val launcher = registerForActivityResult(
    ActivityResultContracts.RequestPermission()
) { granted -> viewModel.onNotificationPermissionResult(granted) }

if (shouldRequestNotifications()) {
    launcher.launch(Manifest.permission.POST_NOTIFICATIONS)
}
